/**
 * Copies static public assets (favicon, manifest) into dist after webpack build.
 * index.html is generated by HtmlWebpackPlugin.
 */
const fs = require("fs");
const path = require("path");
const { writeFaviconIco } = require("./generate-favicon-ico");

const root = path.join(__dirname, "..");
const publicDir = path.join(root, "public");
const distDir = path.join(root, "dist");

const filesToCopy = ["favicon.svg", "favicon.ico", "manifest.json"];

if (!fs.existsSync(distDir)) {
  console.error("copy-public-assets: dist/ not found — run webpack build first.");
  process.exit(1);
}

writeFaviconIco(path.join(publicDir, "favicon.ico"));
writeFaviconIco(path.join(distDir, "favicon.ico"));

for (const file of filesToCopy) {
  const source = path.join(publicDir, file);
  const target = path.join(distDir, file);

  if (!fs.existsSync(source)) {
    console.warn(`copy-public-assets: skipping missing ${file}`);
    continue;
  }

  fs.copyFileSync(source, target);
  console.log(`copy-public-assets: ${file} → dist/`);
}
